//! Terminal client code generation for the Rust shell.
//!
//! Emits the `src/bin/terminal.rs` entry point that launches the native ratatui
//! terminal client this shell ships (`renderers/tui`).

/// Generate the `src/bin/terminal.rs` source for the generated application.
pub fn generate_tui_bin() -> String {
    r#"//! Native terminal client entry point.
//!
//! Generated by the Orbital Rust shell. Run with:
//!   cargo run --bin terminal
//!
//! The terminal client communicates with the Orbital server (default
//! http://127.0.0.1:3030) using the closed-circuit event protocol.

use std::path::Path;

fn main() -> anyhow::Result<()> {
    let server_url = std::env::var("SERVER_URL")
        .ok()
        .or_else(|| Some("http://127.0.0.1:3030".to_string()));

    orbital_client_tui::run(Path::new("resolved.orb"), server_url.as_deref())
}
"#
    .to_string()
}

/// Generate `src/main.rs` for the standalone terminal binary: the resolved program is compiled in
/// and the client kernel runs in-process, so the binary needs no server and reads no file from cwd.
pub fn generate_tui_standalone_main() -> String {
    r#"//! Standalone terminal program. Generated by the Orbital Rust shell.

const PROGRAM: &str = include_str!("../program.orb");

fn main() -> anyhow::Result<()> {
    let schema = orbital_core::schema::parse_schema(PROGRAM)?;
    orbital_client_tui::run_program(schema)
}
"#
    .to_string()
}
